const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoiAswan = ee.Geometry.Point(32.8800, 23.9708).buffer(10000); // Aswan High Dam, 10km buffer
  const aoiGERD = ee.Geometry.Point(35.0934, 11.2062).buffer(10000); // Grand Ethiopian Renaissance Dam, 10km buffer
  const year = '2016';
  const startDate = ee.Date.fromYMD(parseInt(year), 1, 1);
  const endDate = ee.Date.fromYMD(parseInt(year), 12, 31);

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSL')
    .filterDate(startDate, endDate)
    .select('avg_rad'); // Select the average radiance band

  const collectionSize = viirsCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log(`No VIIRS DNB images found for ${year}.`);
    console.log("C1");
    return;
  }

  // Reduce the collection to a single image by taking the mean for the year
  const yearlyBrightness = viirsCollection.mean();

  if (yearlyBrightness.bandNames().length().getInfo() === 0) {
      console.log("C1"); // No image after reducing the collection (should not happen if size > 0, but good to check)
      return;
  }

  // Function to get brightness for a given AOI
  const getBrightness = async (aoi, name) => {
    const scale = 1000; // Use a reasonable scale to avoid memory issues and ensure accuracy
    const maxPixels = 1e9;

    // Calculate pixel count within the AOI
    const countPixels = yearlyBrightness.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('avg_rad');

    const validPixels = await ee.Number(countPixels).getInfo();

    if (validPixels === 0) {
      console.log(`No valid pixels found for ${name} after processing.`);
      return { brightness: null, validPixels: 0 };
    }

    // Calculate mean brightness
    const meanBrightness = yearlyBrightness.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('avg_rad');

    const brightnessValue = await ee.Number(meanBrightness).getInfo();

    if (brightnessValue === null || isNaN(brightnessValue)) {
      console.log(`Calculation failed for ${name}. Result is None/NaN.`);
      return { brightness: null, validPixels: validPixels };
    }
    return { brightness: brightnessValue, validPixels: validPixels };
  };

  // 3. & 4. Processing & Calculation
  const aswanResult = await getBrightness(aoiAswan, 'Aswan High Dam');
  const gerdResult = await getBrightness(aoiGERD, 'Grand Ethiopian Renaissance Dam');

  if (aswanResult.brightness === null || gerdResult.brightness === null) {
      if (aswanResult.validPixels === 0 || gerdResult.validPixels === 0) {
          console.log("C2");
      } else {
          console.log("C3");
      }
      return;
  }

  // 5. Validation & Final Answer
  console.log(`Aswan (Avg Rad): ${aswanResult.brightness.toFixed(4)}, Pixels: ${aswanResult.validPixels}`);
  console.log(`GERD (Avg Rad): ${gerdResult.brightness.toFixed(4)}, Pixels: ${gerdResult.validPixels}`);

  if (aswanResult.brightness > gerdResult.brightness) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
